package resolver

import (
	"context"
	"regexp"

	"github.com/devsy-org/devsy/pkg/config"
	"github.com/devsy-org/devsy/pkg/devcontainer/graph"
	"github.com/devsy-org/devsy/pkg/types"
)

const (
	rootID = "root"
)

var variableExpression = regexp.MustCompile(`(?m)\$\{?([A-Z0-9_]+)(:(-|\+)([^\}]+))?\}?`)

func ResolveDefaultValue(val string, resolvedOptions map[string]string) string {
	return variableExpression.ReplaceAllStringFunc(val, func(s string) string {
		submatch := variableExpression.FindStringSubmatch(s)
		optionVal, ok := resolvedOptions[submatch[1]]
		if ok {
			return optionVal
		}

		return s
	})
}

func ResolveDefaultValues(
	vals map[string]string,
	resolvedOptions map[string]string,
) map[string]string {
	ret := make(map[string]string)
	for k, v := range vals {
		resolvedValue := ResolveDefaultValue(v, resolvedOptions)
		if resolvedValue == "" {
			continue
		}

		ret[k] = resolvedValue
	}
	return ret
}

type Resolver struct {
	// user provided
	userOptions map[string]string
	// extra values
	extraValues map[string]string

	// internal
	graph *graph.Graph[*types.Option]

	// options
	resolveLocal      bool
	resolveGlobal     bool
	resolveSubOptions bool
	skipRequired      bool
}

type Option func(r *Resolver)

func New(
	userOptions map[string]string,
	extraValues map[string]string,
	opts ...Option,
) *Resolver {
	if userOptions == nil {
		userOptions = map[string]string{}
	}

	resolver := &Resolver{
		userOptions: userOptions,
		extraValues: extraValues,
	}
	for _, o := range opts {
		o(resolver)
	}

	return resolver
}

func WithResolveLocal() Option {
	return func(r *Resolver) {
		r.resolveLocal = true
	}
}

func WithResolveGlobal() Option {
// ResolveAgentConfig resolves and returns the complete agent configuration for a provider.
